/*
 * JAB Code browser runtime.
 *
 * This is a self-contained loader for the JAB Code encoder/decoder compiled
 * to WebAssembly with Zig (target wasm32-wasi). It replaces the upstream
 * TMSSassen/JABCodeJS distribution, whose committed build ships a
 * `<<< WASM_BINARY_FILE >>>` placeholder in place of the actual wasm, so it
 * cannot produce or read a real JAB Code.
 *
 * The public surface is kept identical to the upstream module so the rest of
 * the app is untouched: `new JabcodeJSInterface()` with `encode_message(text,
 * symbols, colors)` -> PNG data-URL string, and `decode_message(blob)` ->
 * Promise<string>.
 */
const WASM_URL = new URL("./jabcode.wasm", import.meta.url).href;

let modulePromise;
async function instantiateWasm() {
    if (modulePromise) return modulePromise;
    modulePromise = (async () => {
        const wasmBytes = await (await fetch(WASM_URL)).arrayBuffer();

        // WASI v1 (preview1) imports the wasm was built against. The library
        // only needs a monotonic clock and a randomness source at runtime.
        let memory;
        const importObject = {
            wasi_snapshot_preview1: {
                clock_time_get: (id, precision, outPtr) => {
                    const view = new DataView(memory.buffer);
                    view.setBigUint64(outPtr, BigInt(Date.now()) * 1000000n, true);
                    return 0;
                },
                random_get: (bufPtr, len) => {
                    const bytes = new Uint8Array(memory.buffer);
                    const tmp = new Uint8Array(len);
                    if (typeof crypto !== "undefined" && crypto.getRandomValues) {
                        crypto.getRandomValues(tmp);
                    } else {
                        for (let i = 0; i < len; i++) tmp[i] = (Math.random() * 256) | 0;
                    }
                    bytes.set(tmp, bufPtr);
                    return 0;
                },
                fd_write: () => 0,
                fd_read: () => 0,
                proc_exit: () => { throw new Error("JAB wasm exited"); },
                environ_get: () => 0,
                environ_sizes_get: () => 0,
                args_get: () => 0,
                args_sizes_get: () => 0,
                fd_close: () => 0,
                fd_seek: () => 0,
                fd_fdstat_get: () => 0,
                fd_fdstat_set_flags: () => 0,
                path_open: () => 0,
                path_filestat_get: () => 0,
                fd_prestat_get: () => 8,
                fd_prestat_dir_name: () => 0,
                poll_oneoff: () => 0,
                sched_yield: () => 0,
            },
            wasi_unstable: {},
        };

        const result = await WebAssembly.instantiate(wasmBytes, importObject);
        const exports = result.instance.exports;
        memory = exports.memory;
        if (typeof exports.__wasm_call_ctors === "function") exports.__wasm_call_ctors();
        return exports;
    })();
    return modulePromise;
}

// ---- Pure-JS PNG writer (BSD, Robert Eisele / PNGlib) ----
function pnglib(width, height, depth) {
    function write(buffer, offs) {
        for (let i = 2; i < arguments.length; i++) {
            const str = arguments[i];
            for (let j = 0; j < str.length; j++) buffer[offs++] = str.charAt(j);
        }
    }
    function byte2(w) { return String.fromCharCode((w >> 8) & 255, w & 255); }
    function byte4(w) { return String.fromCharCode((w >> 24) & 255, (w >> 16) & 255, (w >> 8) & 255, w & 255); }
    function byte2lsb(w) { return String.fromCharCode(w & 255, (w >> 8) & 255); }

    const pix_size = height * (width + 1);
    const data_size = 2 + pix_size + 5 * Math.floor((0xfffe + pix_size) / 0xffff) + 4;
    const ihdr_size = 4 + 4 + 13 + 4;
    const plte_offs = ihdr_size;
    const plte_size = 4 + 4 + 3 * depth + 4;
    const trns_offs = plte_offs + plte_size;
    const trns_size = 4 + 4 + depth + 4;
    const idat_offs = trns_offs + trns_size;
    const idat_size = 4 + 4 + data_size + 4;
    const iend_offs = idat_offs + idat_size;
    const iend_size = 12;
    const buffer_size = iend_offs + iend_size;

    const buffer = new Array(buffer_size);
    const palette = {};
    let pindex = 0;
    const crcTable = new Array(256);
    for (let i = 0; i < buffer_size; i++) buffer[i] = "\x00";
    write(buffer, 0, byte4(ihdr_size - 12), "IHDR", byte4(width), byte4(height), "\x08\x03");
    write(buffer, plte_offs, byte4(plte_size - 12), "PLTE");
    write(buffer, trns_offs, byte4(trns_size - 12), "tRNS");
    write(buffer, idat_offs, byte4(idat_size - 12), "IDAT");
    write(buffer, iend_offs, byte4(iend_size - 12), "IEND");
    const header = (((8 + (7 << 4)) << 8) | (3 << 6)) + 31 - ((((8 + (7 << 4)) << 8) | (3 << 6)) % 31);
    write(buffer, idat_offs + 8, byte2(header));
    for (let i = 0; (i << 16) - 1 < pix_size; i++) {
        let size, bits;
        if (i + 0xffff < pix_size) { size = 0xffff; bits = "\x00"; }
        else { size = pix_size - (i << 16) - i; bits = "\x01"; }
        write(buffer, idat_offs + 8 + 2 + (i << 16) + (i << 2), bits, byte2lsb(size), byte2lsb(~size));
    }
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) c = (c & 1) ? (-306674912 ^ ((c >> 1) & 0x7fffffff)) : (c >> 1) & 0x7fffffff;
        crcTable[i] = c;
    }
    const index = (x, y) => {
        const i = y * (width + 1) + x + 1;
        return idat_offs + 8 + 2 + 5 * Math.floor(i / 0xffff + 1) + i;
    };
    const color = (red, green, blue, alpha) => {
        alpha = alpha >= 0 ? alpha : 255;
        const c = (((((alpha << 8) | red) << 8) | green) << 8) | blue;
        if (typeof palette[c] === "undefined") {
            if (pindex === depth) return "\x00";
            const ndx = plte_offs + 8 + 3 * pindex;
            buffer[ndx + 0] = String.fromCharCode(red);
            buffer[ndx + 1] = String.fromCharCode(green);
            buffer[ndx + 2] = String.fromCharCode(blue);
            buffer[trns_offs + 8 + pindex] = String.fromCharCode(alpha);
            palette[c] = String.fromCharCode(pindex++);
        }
        return palette[c];
    };
    const getDump = () => {
        const BASE = 65521, NMAX = 5552;
        let s1 = 1, s2 = 0, n = NMAX;
        for (let y = 0; y < height; y++) {
            for (let x = -1; x < width; x++) {
                s1 += buffer[index(x, y)].charCodeAt(0);
                s2 += s1;
                if ((n -= 1) === 0) { s1 %= BASE; s2 %= BASE; n = NMAX; }
            }
        }
        s1 %= BASE; s2 %= BASE;
        write(buffer, idat_offs + idat_size - 8, byte4((s2 << 16) | s1));
        function crc32(png, offs, size) {
            let crc = -1;
            for (let i = 4; i < size - 4; i += 1) crc = crcTable[(crc ^ png[offs + i].charCodeAt(0)) & 0xff] ^ ((crc >> 8) & 0x00ffffff);
            write(png, offs + size - 4, byte4(crc ^ -1));
        }
        crc32(buffer, 0, ihdr_size);
        crc32(buffer, plte_offs, plte_size);
        crc32(buffer, trns_offs, trns_size);
        crc32(buffer, idat_offs, idat_size);
        crc32(buffer, iend_offs, iend_size);
        return "\x89PNG\r\n\x1a\n" + buffer.join("");
    };
    return { buffer, index, color, getDump };
}

class JabcodeJSInterface {
    async _ready() {
        return instantiateWasm();
    }

    /**
     * Encode a string into a JAB Code and return it as a PNG data URL.
     * `symbols` is the symbol count, `colors` the palette size (e.g. 8).
     */
    async encode_message(text, symbols, colors) {
        const exp = await instantiateWasm();
        const { memory, encode_image, getDefaultColorNumber } = exp;
        const symCount = symbols || 1;
        const colCount = colors || getDefaultColorNumber();

        const bytes = new TextEncoder().encode(text);
        const ptr = exp.malloc(bytes.length + 1);
        const heap = new Uint8Array(memory.buffer);
        heap.set(bytes, ptr);
        heap[ptr + bytes.length] = 0;

        const result = encode_image(ptr, colCount, symCount);
        exp.free(ptr);
        if (!result) throw new Error("JAB Code encoding failed");

        const view = new DataView(memory.buffer);
        const width = view.getInt32(result, true);
        const height = view.getInt32(result + 4, true);
        const pixlen = view.getInt32(result + 12, true);
        const pixStart = result + 16;
        const depth = colCount;

        const png = pnglib(width, height, depth);
        const pixels = new Uint8Array(memory.buffer, pixStart, pixlen);
        for (let y = 0; y < height; y++) {
            for (let x = 0; x < width; x++) {
                const o = (y * width + x) * 4;
                png.buffer[png.index(x, y)] = png.color(pixels[o], pixels[o + 1], pixels[o + 2], pixels[o + 3]);
            }
        }
        exp.free(result);
        const b64 = btoa(png.getDump());
        return "data:image/png;base64," + b64;
    }

    /**
     * Decode a JAB Code image (PNG blob or data URL / ArrayBuffer) and return
     * the message string.
     */
    async decode_message(input) {
        const exp = await instantiateWasm();
        const { memory, decode_image } = exp;

        // Turn input into a bitmap of RGBA bytes.
        let width, height, rgba;
        if (input && typeof input === "string") {
            const base64 = input.slice(input.indexOf(",") + 1);
            const bin = atob(base64);
            const data = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) data[i] = bin.charCodeAt(i);
            rgba = await pngDecodeBytes(data);
            width = rgba.w; height = rgba.h; rgba = rgba.data;
        } else if (input instanceof ArrayBuffer) {
            rgba = await pngDecodeBytes(new Uint8Array(input));
            width = rgba.w; height = rgba.h; rgba = rgba.data;
        } else if (typeof createImageBitmap !== "undefined") {
            const bmp = await createImageBitmap(input);
            const canvas = document.createElement("canvas");
            canvas.width = bmp.width; canvas.height = bmp.height;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(bmp, 0, 0);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            width = canvas.width; height = canvas.height;
            rgba = new Uint8Array(imageData.data);
        } else {
            throw new Error("JAB: unsupported image input");
        }

        const pixlen = width * height * 4;
        const rgbaPtr = exp.malloc(pixlen);
        new Uint8Array(memory.buffer).set(rgba, rgbaPtr);
        const result = decode_image(rgbaPtr, width, height);
        exp.free(rgbaPtr);
        if (!result) return "";

        const view = new DataView(memory.buffer);
        const len = view.getInt32(result, true);
        const outBytes = new Uint8Array(memory.buffer, result + 16, len);
        const text = new TextDecoder().decode(outBytes);
        exp.free(result);
        return text;
    }
}

// PNG decoder (returns {w,h,data:RGBA}) - browser path via ImageBitmap/canvas.
async function pngDecodeBytes(bytes) {
    if (typeof createImageBitmap !== "undefined") {
        const blob = new Blob([bytes], { type: "image/png" });
        const bmp = await createImageBitmap(blob);
        const canvas = document.createElement("canvas");
        canvas.width = bmp.width; canvas.height = bmp.height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(bmp, 0, 0);
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        return { w: canvas.width, h: canvas.height, data: new Uint8Array(imageData.data) };
    }
    throw new Error("JAB: PNG decoding requires createImageBitmap/canvas");
}

export default JabcodeJSInterface;
